        Opportunity oppB2 = new Opportunity(Name='B2', AccountId=null, StageName='Closed Won', CloseDate=Date.today().addDays(5), Amount=100);
        Opportunity oppB3 = new Opportunity(Name='B3', AccountId=accts[0].Id, StageName='Prospecting', CloseDate=Date.today().addDays(5), Amount=100);
        Opportunity oppB4 = new Opportunity(Name='B4', AccountId=accts[1].Id, StageName='Prospecting', CloseDate=Date.today().addDays(5), Amount=100);

        List<Opportunity> opps = new List<Opportunity>{oppB1, oppB2, oppB3, oppB4};
