public class PicklistService {
    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;
    }

    public class PicklistServiceException extends Exception {}

    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name cannot be null or blank.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name cannot be null or blank.');
        }

        Schema.SObjectType sObjectType = null;
        Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();
        for (String key : globalDescribe.keySet()) {
            if (key.equalsIgnoreCase(objectApiName)) {
                sObjectType = globalDescribe.get(key);
                break;
            }
        }
        if (sObjectType == null) {
            throw new PicklistServiceException('Object does not exist: ' + objectApiName);
        }

        Schema.DescribeSObjectResult sObjectDescribe = sObjectType.getDescribe();
        Map<String, Schema.SObjectField> fieldMap = sObjectDescribe.fields.getMap();
        Schema.SObjectField sObjectField = null;
        for (String key : fieldMap.keySet()) {
            if (key.equalsIgnoreCase(fieldApiName)) {
                sObjectField = fieldMap.get(key);
                break;
            }
        }
        if (sObjectField == null) {
            throw new PicklistServiceException('Field does not exist on object: ' + fieldApiName);
        }

        Schema.DescribeFieldResult fieldDescribe = sObjectField.getDescribe();
        Schema.DescribeFieldResult.FieldType fieldType = fieldDescribe.getType();
        if (fieldType != Schema.DescribeFieldResult.FieldType.Picklist &&
            fieldType != Schema.DescribeFieldResult.FieldType.MultiPicklist) {
            throw new PicklistServiceException('Field is not a picklist or multi-select picklist: ' + fieldApiName);
        }

        List<Schema.PicklistEntry> entries = fieldDescribe.getPicklistValues();
        List<Option> options = new List<Option>();

        for (Schema.PicklistEntry entry : entries) {
            if (entry.isActive()) {
                Option opt = new Option();
                opt.value = entry.getValue();
                opt.label = entry.getLabel();
                opt.isDefault = entry.isDefaultValue();
                options.add(opt);
            }
        }

        return options;
    }
}
