            Opportunity oldOpp = (Opportunity) Trigger.oldMap.get(opp.Id);
            if (opp.StageName == 'Closed Won' && oldOpp != null && oldOpp.StageName != 'Closed Won') {
                opportunityIdsToProcess.add(opp.Id);
