public class Opportunities extends fflib_SObjectDomain {
    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities(records);
        }
    }

    public Opportunities(List<SObject> records) {
        super(records);
    }

    public override void onBeforeInsert(List<SObject> records) {
        super.onBeforeInsert(records);
        for (Opportunity opp : (List<Opportunity>) records) {
            if (opp.Amount < 0) {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }
    }

    public override void onBeforeUpdate(List<SObject> oldRecords, List<SObject> newRecords) {
        super.onBeforeUpdate(oldRecords, newRecords);
        for (Integer i = 0; i < newRecords.size(); i++) {
            Opportunity newOpp = (Opportunity) newRecords[i];
            Opportunity oldOpp = (Opportunity) oldRecords[i];

            if (newOpp.Amount < 0) {
                error('Amount cannot be negative.', newOpp, Opportunity.Amount);
            }

            if (oldOpp.StageName == 'Closed Won' && newOpp.Amount != oldOpp.Amount) {
                error('Amount cannot change on a won opportunity.', newOpp, Opportunity.Amount);
            }
        }
    }
}
