public with sharing class AccountOnboardingService {
    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return new List<Account>();
        }

        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(new List<Schema.SObjectType> {
            Account.SObjectType,
            Contact.SObjectType
        });

        Map<String, Account> accountMap = new Map<String, Account>();

        // Create and register Accounts
        for (String accountName : contactLastNamesByAccountName.keySet()) {
            Account acct = new Account(Name = accountName);
            uow.registerNew(acct);
            accountMap.put(accountName, acct);
        }

        // Create and register Contacts
        for (String accountName : contactLastNamesByAccountName.keySet()) {
            Account acct = accountMap.get(accountName);
            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames != null) {
                for (String ln : lastNames) {
                    if (String.isBlank(ln)) {
                        continue;
                    }
                    Contact contact = new Contact();
                    contact.LastName = ln;
                    contact.Account = acct;
                    uow.registerNew(contact);
                }
            }
        }

        uow.commitWork();

        return new List<Account>(accountMap.values());
    }
}
