        this.data = [...(value || [])];
    }

    get opportunities() {
        return this.data;
    }

    get columns() {
        return [
            { fieldName: 'Name', label: 'Name' },
            { fieldName: 'StageName', label: 'Stage' },
            { fieldName: 'Amount', label: 'Amount', type: 'currency' },
            {
                type: 'action',
                typeAttributes: {
                    rowActions: [
                        { label: 'View', name: 'view' },
                        { label: 'Edit', name: 'edit' },
                        { label: 'Delete', name: 'delete' }
                    ]
                }
            }
        ];
    }

    async handleRowAction(event) {
        const actionName = event.detail.action.name;
        const row = event.detail.row;

        switch (actionName) {
            case 'view':
                this[NavigationMixin.Navigate]({
                    type: 'standard__recordPage',
                    attributes: {
                        recordId: row.Id,
                        actionName: 'view'
                    }
                });
                break;
            case 'edit':
                this[NavigationMixin.Navigate]({
                    type: 'standard__recordPage',
                    attributes: {
                        recordId: row.Id,
                        actionName: 'edit'
                    }
                });
                break;
            case 'delete':
                try {
                    await LightningConfirm.open({ message: 'Are you sure you want to delete this opportunity?' });
                    await deleteRecord(row.Id);
                    this.data = this.data.filter(item => item.Id !== row.Id);
                    this.dispatchEvent(new ShowToastEvent({ title: 'Opportunity deleted', variant: 'success' }));
                } catch (error) {
                    if (error.body && error.body.message) {
                        this.dispatchEvent(new ShowToastEvent({ title: 'Delete failed', message: error.body.message, variant: 'error' }));
                    }
                }
                break;
        }
    }
}
